/// PLIC Interrupt Source Peripheral.
///
/// Enumeration used to determine which peripheral asserted the corresponding
/// interrupt.
#[derive(Copy, Clone, PartialEq, Eq)]
#[repr(u32)]
pub enum PlicPeripheral {
    /// Unknown Peripheral
    Unknown = 0,
    /// hmac
    Hmac = 1,
    /// kmac
    Kmac = 2,
    /// csrng
    Csrng = 3,
    /// entropy_src
    EntropySrc = 4,
    /// edn0
    Edn0 = 5,
    /// otbn
    Otbn = 6,
    /// keymgr
    Keymgr = 7,
    /// alert_handler
    AlertHandler = 8,
    /// otp_ctrl
    OtpCtrl = 9,
    /// sensor_ctrl
    SensorCtrl = 10,
    /// spi_device
    SpiDevice = 11,
    /// gpio
    Gpio = 12,
    /// i2c0
    I2c0 = 13,
    /// uart0
    Uart0 = 14,
    /// rv_timer
    RvTimer = 15,
    /// aon_timer_aon
    AonTimerAon = 16,
    /// pwrmgr_aon
    PwrmgrAon = 17,
    /// flash_ctrl
    FlashCtrl = 18,
}

impl TryFrom<u32> for PlicPeripheral {
    type Error = u32;
    fn try_from(val: u32) -> Result<Self, Self::Error> {
        match val {
            0 => Ok(Self::Unknown),
            1 => Ok(Self::Hmac),
            2 => Ok(Self::Kmac),
            3 => Ok(Self::Csrng),
            4 => Ok(Self::EntropySrc),
            5 => Ok(Self::Edn0),
            6 => Ok(Self::Otbn),
            7 => Ok(Self::Keymgr),
            8 => Ok(Self::AlertHandler),
            9 => Ok(Self::OtpCtrl),
            10 => Ok(Self::SensorCtrl),
            11 => Ok(Self::SpiDevice),
            12 => Ok(Self::Gpio),
            13 => Ok(Self::I2c0),
            14 => Ok(Self::Uart0),
            15 => Ok(Self::RvTimer),
            16 => Ok(Self::AonTimerAon),
            17 => Ok(Self::PwrmgrAon),
            18 => Ok(Self::FlashCtrl),
            _ => Err(val),
        }
    }
}

