impl TryFrom<u32> for PlicIrqId {
    type Error = u32;
    fn try_from(val: u32) -> Result<Self, Self::Error> {
        match val {
            0 => Ok(Self::None),
            1 => Ok(Self::HmacHmacDone),
            2 => Ok(Self::HmacFifoEmpty),
            3 => Ok(Self::HmacHmacErr),
            4 => Ok(Self::KmacKmacDone),
            5 => Ok(Self::KmacFifoEmpty),
            6 => Ok(Self::KmacKmacErr),
            7 => Ok(Self::CsrngCsCmdReqDone),
            8 => Ok(Self::CsrngCsEntropyReq),
            9 => Ok(Self::CsrngCsHwInstExc),
            10 => Ok(Self::CsrngCsFatalErr),
            11 => Ok(Self::EntropySrcEsEntropyValid),
            12 => Ok(Self::EntropySrcEsHealthTestFailed),
            13 => Ok(Self::EntropySrcEsObserveFifoReady),
            14 => Ok(Self::EntropySrcEsFatalErr),
            15 => Ok(Self::Edn0EdnCmdReqDone),
            16 => Ok(Self::Edn0EdnFatalErr),
            17 => Ok(Self::OtbnDone),
            18 => Ok(Self::KeymgrOpDone),
            19 => Ok(Self::AlertHandlerClassa),
            20 => Ok(Self::AlertHandlerClassb),
            21 => Ok(Self::AlertHandlerClassc),
            22 => Ok(Self::AlertHandlerClassd),
            23 => Ok(Self::OtpCtrlOtpOperationDone),
            24 => Ok(Self::OtpCtrlOtpError),
            25 => Ok(Self::SensorCtrlIoStatusChange),
            26 => Ok(Self::SensorCtrlInitStatusChange),
            27 => Ok(Self::SpiDeviceUploadCmdfifoNotEmpty),
            28 => Ok(Self::SpiDeviceUploadPayloadNotEmpty),
            29 => Ok(Self::SpiDeviceUploadPayloadOverflow),
            30 => Ok(Self::SpiDeviceReadbufWatermark),
            31 => Ok(Self::SpiDeviceReadbufFlip),
            32 => Ok(Self::SpiDeviceTpmHeaderNotEmpty),
            33 => Ok(Self::SpiDeviceTpmRdfifoCmdEnd),
            34 => Ok(Self::SpiDeviceTpmRdfifoDrop),
            35 => Ok(Self::GpioGpio0),
            36 => Ok(Self::GpioGpio1),
            37 => Ok(Self::GpioGpio2),
            38 => Ok(Self::GpioGpio3),
            39 => Ok(Self::GpioGpio4),
            40 => Ok(Self::GpioGpio5),
            41 => Ok(Self::GpioGpio6),
            42 => Ok(Self::GpioGpio7),
            43 => Ok(Self::GpioGpio8),
            44 => Ok(Self::GpioGpio9),
            45 => Ok(Self::GpioGpio10),
            46 => Ok(Self::GpioGpio11),
            47 => Ok(Self::GpioGpio12),
            48 => Ok(Self::GpioGpio13),
            49 => Ok(Self::GpioGpio14),
            50 => Ok(Self::GpioGpio15),
            51 => Ok(Self::GpioGpio16),
            52 => Ok(Self::GpioGpio17),
            53 => Ok(Self::GpioGpio18),
            54 => Ok(Self::GpioGpio19),
            55 => Ok(Self::GpioGpio20),
            56 => Ok(Self::GpioGpio21),
            57 => Ok(Self::GpioGpio22),
            58 => Ok(Self::GpioGpio23),
            59 => Ok(Self::GpioGpio24),
            60 => Ok(Self::GpioGpio25),
            61 => Ok(Self::GpioGpio26),
            62 => Ok(Self::GpioGpio27),
            63 => Ok(Self::GpioGpio28),
            64 => Ok(Self::GpioGpio29),
            65 => Ok(Self::GpioGpio30),
            66 => Ok(Self::GpioGpio31),
            67 => Ok(Self::I2c0FmtThreshold),
            68 => Ok(Self::I2c0RxThreshold),
            69 => Ok(Self::I2c0AcqThreshold),
            70 => Ok(Self::I2c0RxOverflow),
            71 => Ok(Self::I2c0ControllerHalt),
            72 => Ok(Self::I2c0SclInterference),
            73 => Ok(Self::I2c0SdaInterference),
            74 => Ok(Self::I2c0StretchTimeout),
            75 => Ok(Self::I2c0SdaUnstable),
            76 => Ok(Self::I2c0CmdComplete),
            77 => Ok(Self::I2c0TxStretch),
            78 => Ok(Self::I2c0TxThreshold),
            79 => Ok(Self::I2c0AcqStretch),
            80 => Ok(Self::I2c0UnexpStop),
            81 => Ok(Self::I2c0HostTimeout),
            82 => Ok(Self::Uart0TxWatermark),
            83 => Ok(Self::Uart0RxWatermark),
            84 => Ok(Self::Uart0TxDone),
            85 => Ok(Self::Uart0RxOverflow),
            86 => Ok(Self::Uart0RxFrameErr),
            87 => Ok(Self::Uart0RxBreakErr),
            88 => Ok(Self::Uart0RxTimeout),
            89 => Ok(Self::Uart0RxParityErr),
            90 => Ok(Self::Uart0TxEmpty),
            91 => Ok(Self::RvTimerTimerExpiredHart0Timer0),
            92 => Ok(Self::AonTimerAonWkupTimerExpired),
            93 => Ok(Self::AonTimerAonWdogTimerBark),
            94 => Ok(Self::PwrmgrAonWakeup),
            95 => Ok(Self::FlashCtrlProgEmpty),
            96 => Ok(Self::FlashCtrlProgLvl),
            97 => Ok(Self::FlashCtrlRdFull),
            98 => Ok(Self::FlashCtrlRdLvl),
            99 => Ok(Self::FlashCtrlOpDone),
            100 => Ok(Self::FlashCtrlCorrErr),
            _ => Err(val),
        }
    }
}

